<?php
require_once __DIR__.'/../../includes/auth.php';
require_once __DIR__.'/../../includes/company_party_helper.php';
$error='';$success='';$userId=$_SESSION['user_id']??null;
if($_SERVER['REQUEST_METHOD']==='POST'){
 try{
  $action=$_POST['action']??'save';
  if($action==='save'){
   $id=(int)($_POST['id']??0);$name=trim($_POST['display_name']??'');$type=$_POST['party_type']??'individual';$status=$_POST['status']??'active';
   if($name==='')throw new Exception('Nama pihak/PIC wajib diisi.');
   $pdo->beginTransaction();
   if($id){$s=$pdo->prepare("UPDATE company_parties SET party_type=:type,display_name=:name,phone=:phone,email=:email,identity_number=:identity,tax_number=:tax,address=:address,bank_name=:bank,bank_account_number=:number,bank_account_name=:account_name,status=:status,notes=:notes,updated_at=NOW() WHERE id=:id");$s->execute([':type'=>$type,':name'=>$name,':phone'=>trim($_POST['phone']??''),':email'=>trim($_POST['email']??''),':identity'=>trim($_POST['identity_number']??''),':tax'=>trim($_POST['tax_number']??''),':address'=>trim($_POST['address']??''),':bank'=>trim($_POST['bank_name']??''),':number'=>trim($_POST['bank_account_number']??''),':account_name'=>trim($_POST['bank_account_name']??''),':status'=>$status,':notes'=>trim($_POST['notes']??''),':id'=>$id]);}
   else{$s=$pdo->prepare("INSERT INTO company_parties(party_code,party_type,display_name,phone,email,identity_number,tax_number,address,bank_name,bank_account_number,bank_account_name,status,notes,created_by) VALUES(:code,:type,:name,:phone,:email,:identity,:tax,:address,:bank,:number,:account_name,:status,:notes,:user)");$s->execute([':code'=>party_generate_code($pdo),':type'=>$type,':name'=>$name,':phone'=>trim($_POST['phone']??''),':email'=>trim($_POST['email']??''),':identity'=>trim($_POST['identity_number']??''),':tax'=>trim($_POST['tax_number']??''),':address'=>trim($_POST['address']??''),':bank'=>trim($_POST['bank_name']??''),':number'=>trim($_POST['bank_account_number']??''),':account_name'=>trim($_POST['bank_account_name']??''),':status'=>$status,':notes'=>trim($_POST['notes']??''),':user'=>$userId]);$id=(int)$pdo->lastInsertId();}
   $pdo->prepare("DELETE FROM company_party_roles WHERE party_id=:id")->execute([':id'=>$id]);
   $roleStmt=$pdo->prepare("INSERT INTO company_party_roles(party_id,role_type,ownership_percent,status) VALUES(:party,:role,:ownership,'active')");
   foreach(array_unique($_POST['roles']??[]) as $role){if(!in_array($role,['shareholder','director','president_commissioner','commissioner','consultant','employee','partner','supplier','other'],true))continue;$roleStmt->execute([':party'=>$id,':role'=>$role,':ownership'=>$role==='shareholder'?(float)($_POST['ownership_percent']??0):null]);}
   $pdo->commit();$success='Data Pihak/PIC berhasil disimpan.';
  }
 }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e->getMessage();}
}
$edit=null;if(isset($_GET['edit'])){$s=$pdo->prepare("SELECT * FROM company_parties WHERE id=:id");$s->execute([':id'=>(int)$_GET['edit']]);$edit=$s->fetch(PDO::FETCH_ASSOC);}
$editRoles=[];if($edit){$s=$pdo->prepare("SELECT role_type,ownership_percent FROM company_party_roles WHERE party_id=:id AND status='active'");$s->execute([':id'=>$edit['id']]);foreach($s->fetchAll(PDO::FETCH_ASSOC) as $r){$editRoles[]=$r['role_type'];if($r['role_type']==='shareholder')$edit['ownership_percent']=$r['ownership_percent'];}}
$parties=party_active_list($pdo);$roleOptions=['shareholder','director','president_commissioner','commissioner','consultant','employee','partner','supplier','other'];
$pageTitle='Pihak/PIC Perusahaan - Nukari';require_once __DIR__.'/../../includes/header.php';require_once __DIR__.'/../../includes/sidebar.php';?>
<main class="main-content"><div class="page-header"><h1 class="fw-bold mb-1">Pihak/PIC Perusahaan</h1><p class="text-muted mb-0">Direktur, komisaris, pemegang saham, konsultan, karyawan, dan pihak lain yang berhubungan dengan dana perusahaan.</p></div>
<?php if($error):?><div class="alert alert-danger"><?=htmlspecialchars($error);?></div><?php endif;?><?php if($success):?><div class="alert alert-success"><?=htmlspecialchars($success);?></div><?php endif;?>
<div class="row g-4"><div class="col-lg-5"><div class="panel"><h5 class="fw-bold mb-3"><?=$edit?'Edit':'Tambah';?> Pihak/PIC</h5><form method="post" class="row g-3"><?=csrf_field();?><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=(int)($edit['id']??0);?>">
<div class="col-md-5"><label class="form-label">Jenis</label><select name="party_type" class="form-select"><option value="individual">Individu</option><option value="organization" <?=($edit['party_type']??'')==='organization'?'selected':'';?>>Badan/Perusahaan</option></select></div><div class="col-md-7"><label class="form-label">Nama *</label><input name="display_name" class="form-control" required value="<?=htmlspecialchars($edit['display_name']??'');?>"></div>
<div class="col-12"><label class="form-label">Hubungan dengan Perusahaan</label><div class="d-flex flex-wrap gap-2"><?php foreach($roleOptions as $role):?><label class="border rounded-pill px-3 py-2"><input type="checkbox" name="roles[]" value="<?=$role;?>" <?=in_array($role,$editRoles,true)?'checked':'';?>> <?=htmlspecialchars(party_role_label($role));?></label><?php endforeach;?></div></div>
<div class="col-md-6"><label class="form-label">Kepemilikan Saham (%)</label><input name="ownership_percent" class="form-control" inputmode="decimal" value="<?=htmlspecialchars($edit['ownership_percent']??'0');?>"></div><div class="col-md-6"><label class="form-label">Status</label><select name="status" class="form-select"><option value="active">Active</option><option value="inactive" <?=($edit['status']??'')==='inactive'?'selected':'';?>>Inactive</option></select></div>
<div class="col-md-6"><label class="form-label">Telepon</label><input name="phone" class="form-control" value="<?=htmlspecialchars($edit['phone']??'');?>"></div><div class="col-md-6"><label class="form-label">Email</label><input type="email" name="email" class="form-control" value="<?=htmlspecialchars($edit['email']??'');?>"></div>
<div class="col-md-6"><label class="form-label">NIK/Identitas</label><input name="identity_number" class="form-control" value="<?=htmlspecialchars($edit['identity_number']??'');?>"></div><div class="col-md-6"><label class="form-label">NPWP</label><input name="tax_number" class="form-control" value="<?=htmlspecialchars($edit['tax_number']??'');?>"></div>
<div class="col-12"><label class="form-label">Alamat</label><textarea name="address" class="form-control" rows="2"><?=htmlspecialchars($edit['address']??'');?></textarea></div><div class="col-md-4"><label class="form-label">Bank</label><input name="bank_name" class="form-control" value="<?=htmlspecialchars($edit['bank_name']??'');?>"></div><div class="col-md-4"><label class="form-label">No. Rekening</label><input name="bank_account_number" class="form-control" value="<?=htmlspecialchars($edit['bank_account_number']??'');?>"></div><div class="col-md-4"><label class="form-label">Nama Rekening</label><input name="bank_account_name" class="form-control" value="<?=htmlspecialchars($edit['bank_account_name']??'');?>"></div>
<div class="col-12"><label class="form-label">Catatan</label><textarea name="notes" class="form-control" rows="2"><?=htmlspecialchars($edit['notes']??'');?></textarea></div><div class="col-12"><button class="btn btn-nukari">Simpan</button><?php if($edit):?><a class="btn btn-light" href="parties.php">Batal</a><?php endif;?></div></form></div></div>
<div class="col-lg-7"><div class="panel"><h5 class="fw-bold mb-3">Daftar Pihak/PIC</h5><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Kode</th><th>Nama</th><th>Hubungan</th><th>Kontak</th><th>Aksi</th></tr></thead><tbody><?php foreach($parties as $p):?><tr><td><b><?=htmlspecialchars($p['party_code']);?></b></td><td><?=htmlspecialchars($p['display_name']);?></td><td><?=htmlspecialchars($p['role_labels']?:'-');?></td><td><?=htmlspecialchars($p['phone']?:$p['email']?:'-');?></td><td><a class="btn btn-sm btn-outline-primary" href="?edit=<?=(int)$p['id'];?>">Edit</a></td></tr><?php endforeach;?><?php if(!$parties):?><tr><td colspan="5" class="text-center text-muted">Belum ada data.</td></tr><?php endif;?></tbody></table></div></div></div></div></main><?php require_once __DIR__.'/../../includes/footer.php';?>
